style.css:
::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-track {
    background: linear-gradient(180deg, red, orange, yellow, green, blue, indigo, violet);
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, violet, indigo, blue, green, yellow, orange, red);
    border-radius: 6px;
}
